from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Preformatted, KeepTogether

ROOT = Path(r"C:\APP\bloodconnect-app-fixed-2\blood connect")
OUT = ROOT / "output" / "pdf" / "BloodConnect_Technical_Guide.pdf"

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="CoverTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=28, leading=34, textColor=colors.HexColor("#8B1E2D"), alignment=TA_CENTER, spaceAfter=16))
styles.add(ParagraphStyle(name="Subtitle", parent=styles["Normal"], fontSize=13, leading=19, alignment=TA_CENTER, textColor=colors.HexColor("#425466")))
styles.add(ParagraphStyle(name="H1x", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=18, leading=24, textColor=colors.HexColor("#8B1E2D"), spaceBefore=8, spaceAfter=10))
styles.add(ParagraphStyle(name="H2x", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=13, leading=17, textColor=colors.HexColor("#0B3157"), spaceBefore=10, spaceAfter=6))
styles.add(ParagraphStyle(name="Bodyx", parent=styles["BodyText"], fontSize=9.5, leading=14, spaceAfter=7))
styles.add(ParagraphStyle(name="CodeTitle", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=9, textColor=colors.HexColor("#FFFFFF"), backColor=colors.HexColor("#0B3157"), borderPadding=5, spaceBefore=6))
styles.add(ParagraphStyle(name="Foot", parent=styles["Normal"], fontSize=7.5, textColor=colors.HexColor("#64748B")))

def p(text, style="Bodyx"):
    return Paragraph(text, styles[style])

def code(title, text):
    return KeepTogether([p(title, "CodeTitle"), Preformatted(text.strip(), ParagraphStyle("Code", fontName="Courier", fontSize=7.2, leading=9.3, backColor=colors.HexColor("#F1F5F9"), borderColor=colors.HexColor("#CBD5E1"), borderWidth=.4, borderPadding=7, spaceAfter=9))])

def footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(colors.HexColor("#CBD5E1")); canvas.line(1.7*cm, 1.4*cm, 19.3*cm, 1.4*cm)
    canvas.setFont("Helvetica", 8); canvas.setFillColor(colors.HexColor("#64748B")); canvas.drawString(1.7*cm, .9*cm, "BloodConnect Technical Guide")
    canvas.drawRightString(19.3*cm, .9*cm, f"Page {doc.page}"); canvas.restoreState()

story = []
story += [Spacer(1, 4.0*cm), p("BloodConnect", "CoverTitle"), p("Technical Guide, Code Reference and Deployment Instructions", "Subtitle"), Spacer(1, .8*cm), p("Prepared from the application source in this workspace. This guide documents the implementation as it exists: React frontend, Spring Boot API, PostgreSQL schema, JWT security and Docker Compose startup.", "Subtitle"), Spacer(1, 4.6*cm), p("Scope note: This is an engineering guide, not a medical protocol. Blood compatibility and operational decisions should be reviewed by qualified clinical and regulatory teams.", "Foot"), PageBreak()]

story += [p("1. System overview", "H1x"), p("BloodConnect is an emergency blood donation coordination platform. It lets users register, create or track blood requests, create donor profiles, receive donor requests and notifications, and supports administrative donor review. The frontend runs as a Vite/React single-page application. The backend is a Spring Boot REST API with PostgreSQL persistence.")]
data = [[p("Layer", "H2x"), p("Technology", "H2x"), p("Responsibility", "H2x")], ["Client", "React 18, Vite, React Router, Zustand, Axios", "Authentication state, route protection, donor and request screens"], ["API", "Java 17, Spring Boot 3.1.5", "REST controllers, validation, business rules, security"], ["Data", "PostgreSQL 15, JPA, Flyway", "Users, profiles, requests, notifications and audit records"], ["Infrastructure", "Docker Compose, Nginx frontend container", "Local multi-container startup and service health checks"]]
t = Table(data, colWidths=[3*cm, 5.2*cm, 9*cm]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#0B3157")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),8.5),("LEADING",(0,0),(-1,-1),11),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAFC")]),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)])); story += [t, Spacer(1,.3*cm), p("Request flow: a requester submits a blood request. The API stores it, asks the matching service for compatible verified and available donors within the configured radius, creates donor-request records, and makes notifications available to the matched donors.")]

story += [p("2. Repository map", "H1x"), p("The codebase separates the browser application from the server application. This is useful because frontend concerns such as routes and forms remain independent from persistence and authorization code."), code("Frontend entry points", "frontend/src/App.jsx                 Route tree and auth-aware navigation\nfrontend/src/pages/                  Screen components\nfrontend/src/services/api.js          Axios API client\nfrontend/src/stores/authStore.js      Zustand authentication state\nfrontend/src/App.css, index.css       Shared styling"), code("Backend entry points", "backend/src/main/java/com/bloodconnect/api/controller/  HTTP endpoints\nbackend/src/main/java/com/bloodconnect/service/         Business logic\nbackend/src/main/java/com/bloodconnect/domain/entity/   JPA entities\nbackend/src/main/java/com/bloodconnect/repository/      Data access\nbackend/src/main/resources/db/migration/                Flyway SQL migrations\nbackend/src/main/resources/application.yml              Runtime configuration")]

story += [p("3. Frontend routing and state", "H1x"), p("App.jsx hydrates the persisted authentication store when the application starts. Routes for login and registration are shown when no user exists; authenticated users receive the home, request, donor and admin routes. This route split prevents the browser from rendering private pages before a user session is available."), code("Auth-aware route structure - frontend/src/App.jsx", "const { user, hydrate } = useAuthStore();\n\nuseEffect(() => {\n  hydrate();\n}, [hydrate]);\n\n{!user ? (\n  <Route path=\"/login\" element={<Login />} />\n) : (\n  <Route path=\"/create-request\" element={<CreateBloodRequest />} />\n)}"), p("Implementation instruction: keep API calls in services/api.js rather than duplicating Axios configuration in page components. Keep session-specific values in authStore.js and clear them on logout. When adding a new authenticated feature, add both a page component and a protected route in App.jsx.")]

story += [p("4. Backend API and authentication", "H1x"), p("Controllers use Spring MVC annotations to expose endpoints. AuthController accepts registration, login and token-refresh requests. BloodRequestController reads the authenticated user ID placed on the request by the JWT filter, then delegates all domain work to BloodRequestService."), code("Login endpoint - backend/.../controller/AuthController.java", "@PostMapping(\"/login\")\npublic ResponseEntity<AuthResponse> login(\n    @Valid @RequestBody AuthRequest request) {\n  AuthResponse response = authService.login(request);\n  return ResponseEntity.ok(response);\n}"), code("Create request endpoint - backend/.../controller/BloodRequestController.java", "@PostMapping\npublic ResponseEntity<BloodRequestResponse> createBloodRequest(\n    @Valid @RequestBody CreateBloodRequestDTO request,\n    HttpServletRequest httpRequest) {\n  Long userId = (Long) httpRequest.getAttribute(\"userId\");\n  BloodRequestResponse response =\n      bloodRequestService.createBloodRequest(request, userId);\n  return ResponseEntity.status(HttpStatus.CREATED).body(response);\n}"), p("Security instruction: set a unique JWT_SECRET outside source control for every environment. The checked-in defaults support only local development. Use HTTPS in production, restrict allowed CORS origins to deployed client domains, and consider rotating refresh tokens and adding rate limiting to login endpoints.")]

story += [p("5. Donor matching logic", "H1x"), p("MatchingService stores a compatibility map keyed by requested blood group. It selects donors whose group appears in the allowed set, whose profiles are VERIFIED and AVAILABLE, and whose coordinates fall inside the request radius. It then sorts candidates by distance."), code("Distance filter - backend/.../service/MatchingService.java", "return donors.stream()\n  .filter(donor -> donor.getLatitude() != null\n                && donor.getLongitude() != null)\n  .filter(donor -> calculateDistance(latitude, longitude,\n       donor.getLatitude(), donor.getLongitude()) <= radiusKm)\n  .sorted((d1, d2) -> Double.compare(\n       calculateDistance(latitude, longitude, d1.getLatitude(), d1.getLongitude()),\n       calculateDistance(latitude, longitude, d2.getLatitude(), d2.getLongitude())))\n  .collect(Collectors.toList());"), p("The distance calculation uses the Haversine formula with an Earth radius of 6,371 km. For larger donor volumes, move the radius search into the database using a geospatial index or PostGIS; the current service fetches qualifying donor groups first and filters coordinates in application memory.")]

story += [p("6. Database design", "H1x"), p("Flyway migration V1 defines the core relational model. users is the identity table. donor_profiles and hospitals extend a user account. blood_requests belongs to a requester and optionally a hospital. donor_requests provides the many-to-many record that captures a donor notification and response. notifications and audit_logs support user communication and traceability.")]
data2=[["Table","Purpose","Important relationships"],["users","Account identity and role","Parent of donor_profiles, hospitals, requests, notifications"],["donor_profiles","Donor eligibility, blood group, availability and location","One profile per user"],["blood_requests","Demand for blood units","Requester user; optional hospital"],["donor_requests","Match and response record","Unique request + donor pair"],["notifications","User-visible event messages","Related entity fields link to request or match"],["audit_logs","Operational activity history","Optional user reference"]]
t2=Table(data2,colWidths=[3.4*cm,6.3*cm,7.5*cm]); t2.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#8B1E2D")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),8.4),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#FFF7F7")]),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)])); story += [t2, p("Schema instruction: create later schema changes as new ordered Flyway migrations. Do not edit a migration that has already been applied in a shared environment.")]

story += [p("7. Local setup and launch", "H1x"), p("Docker Compose is the quickest way to start the three application services. It provisions PostgreSQL, waits for its health check, builds the Spring API, then serves the frontend. The browser-facing frontend port is 3000; API requests use the /api context path and the backend health endpoint is /api/auth/health."), code("Run locally", "# From the repository root\ndocker compose up --build\n\n# Open the frontend\nhttp://localhost:3000\n\n# Check the API health response\nhttp://localhost:8080/api/auth/health"), p("For frontend-only work, run npm install and npm run dev inside frontend. For backend-only work, configure a PostgreSQL database through DB_URL, DB_USERNAME, DB_PASSWORD and JWT_SECRET, then run Maven from backend. The default application.yml listens on port 8080 with a /api context path.")]

story += [p("8. Verification and next steps", "H1x"), p("Before publishing, validate API behavior with unit and integration tests, test role restrictions on every protected endpoint, and test request matching using known locations and blood groups. Confirm errors use consistent response shapes. Review production secrets, database backups, audit-log retention, monitoring and alerting before handling real donor data."), p("Recommended engineering improvements"), p("1. Add integration tests for registration, login, JWT rejection and blood-request creation.<br/>2. Add database-level or geospatial support for scalable nearby-donor searches.<br/>3. Add API documentation with OpenAPI and examples for every controller.<br/>4. Add an environment-specific CORS allowlist and secrets manager integration.<br/>5. Have clinical and legal owners validate the compatibility and donor eligibility rules before production use.")]

doc = SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=1.7*cm, leftMargin=1.7*cm, topMargin=1.7*cm, bottomMargin=1.8*cm, title="BloodConnect Technical Guide", author="Codex")
doc.build(story, onFirstPage=footer, onLaterPages=footer)
print(OUT)
